def test_hypothesis_geometry(input_objects, output_objects):
    input_shape = input_objects[0]['shape']
    output_shape = output_objects[0]['shape']
    return input_shape != output_shape and input_shape == (5, 2) and output_shape == (1, 1)

def test_hypothesis_movement(input_objects, output_objects):
    input_position = input_objects[0]['position']
    output_position = output_objects[0]['position']
    return input_position[0] != output_position[0] and input_position[1] == output_position[1] and output_position == (0, 1)

def test_hypothesis_object(input_objects, output_objects):
    input_colors = set(input_objects[0]['colors'])
    output_colors = set(output_objects[0]['colors'])
    return (5 in input_colors) and (1 in output_colors) and (len(input_colors) == 1) and (len(output_colors) == 1)

def test_hypothesis_commonsense(input_objects, output_objects):
    input_shape = input_objects[0]['shape']
    output_shape = output_objects[0]['shape']
    return input_shape[0] > output_shape[0] and input_shape[1] > output_shape[1] and output_shape == (1, 1)
